    createWebCall: {
        parameters: {
            query?: never;
            header: {
                /** @description Client-generated key (8 to 255 chars), required on POSTs that spend credit or place calls. A replay within 24 h returns the original response. */
                "Idempotency-Key": components["parameters"]["IdempotencyKeyRequired"];
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["WebCallRequest"];
            };
        };
        responses: {
            /** @description Call admitted and room ready */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["WebCallSession"];
                };
            };
            /** @description Missing or malformed `Idempotency-Key` header (`idempotency-key-required`). */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            401: components["responses"]["Problem"];
            /** @description Insufficient credit (`type` ends with `/insufficient-credit`) */
            402: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["CallRefusedProblem"];
                };
            };
            /** @description Email not verified (`type` ends with `/email-unverified`) */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            404: components["responses"]["Problem"];
            /** @description `agent-not-published` (version=published with none pinned), `flow-not-compiled` (a flow agent whose graph has no compiled flow, 004) or `idempotency-key-in-use` (same key, request still running). */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description Invalid variables, unsupported vendor (`unsupported-vendor`), unpriced configuration (`pricing-unavailable`), flow agent without flow runtime (`flow-runtime-unavailable`), or idempotency key reused with a different body. */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["CallRefusedProblem"];
                };
            };
            /** @description Concurrency limit reached (`type` ends with `/concurrency-limit`) */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["CallRefusedProblem"];
                };
            };
            /** @description The media server could not create the room or dispatch the worker (`media-unavailable`). The call is recorded as `failed` and not charged. */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["CallRefusedProblem"];
                };
            };
        };
    };
