    verifyWhatsAppWebhook: {
        parameters: {
            query: {
                "hub.mode": "subscribe";
                "hub.verify_token": string;
                "hub.challenge": string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Echo of `hub.challenge` when the verify token matches a channel */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/plain": string;
                };
            };
            /** @description No channel has this verify token */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/plain": string;
                };
            };
        };
    };
    receiveWhatsAppWebhook: {
        parameters: {
            query?: never;
            header: {
                "X-Hub-Signature-256": string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @constant */
                    object: "whatsapp_business_account";
                    entry: {
                        id?: string;
                        changes?: {
                            /**
                             * @example calls
                             * @example messages
                             */
                            field?: string;
                            value?: {
                                metadata?: {
                                    phone_number_id?: string;
                                    display_phone_number?: string;
                                };
                            } & {
                                [key: string]: unknown;
                            };
                        }[];
                    }[];
                };
            };
        };
        responses: {
            /** @description Accepted, or ignored for unknown numbers */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Signature does not match the channel's app secret */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
